from collections import defaultdict


def transform(grid):
    h, w = len(grid), len(grid[0])
    points = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]
    if not points:
        return [row[:] for row in grid]

    colors = {v for _, _, v in points}
    if len(colors) == 1:
        color = next(iter(colors))
        return [[color for _ in range(w)] for _ in range(h)]

    features = [lambda r, c: r, lambda r, c: c, lambda r, c: r + c, lambda r, c: r - c]
    best_feature = None
    best_score = (-1, -1)
    for feature in features:
        groups = defaultdict(list)
        for r, c, color in points:
            groups[feature(r, c)].append(color)
        good = [values for values in groups.values()
                if len(values) >= 2 and len(set(values)) == 1]
        score = (sum(len(values) for values in good), len(good))
        if score > best_score:
            best_score = score
            best_feature = feature

    max_period = 2 * max(h, w)
    for period in range(1, max_period + 1):
        mapping = {}
        valid = True
        for r, c, color in points:
            residue = best_feature(r, c) % period
            if residue in mapping and mapping[residue] != color:
                valid = False
                break
            mapping[residue] = color
        if valid and len(mapping) == period:
            return [[mapping[best_feature(r, c) % period] for c in range(w)]
                    for r in range(h)]

    raise ValueError("Could not infer a complete periodic diagonal pattern")
